// =========== 1. SRP 单一职责 ===========
// 反例：一个类承担用户、邮件、报表三种变化原因
class UserManager {
    void createUser(User u) { /* ... */ }
    void sendWelcomeEmail(User u) { /* SMTP 细节 */ }
    void exportMonthlyReport() { /* Excel 细节 */ }
}
// 正例：按变化原因拆分，三条变化路径互不影响
class UserService { void createUser(User u) { /* ... */ } }
class EmailService { void sendWelcome(User u) { /* ... */ } }
class ReportService { void exportMonthly() { /* ... */ } }

// =========== 2. OCP 开闭 ===========
// 反例：新增 Shape 必须改 draw 里的 if-else
class ShapeDrawer {
    void draw(Object shape) {
        if (shape instanceof Circle) { /* ... */ }
        else if (shape instanceof Rectangle) { /* ... */ }
        // 新增 Triangle 必须再加分支
    }
}
// 正例：抽象 + 多态，新增类型不改老代码
interface Shape { void draw(); }
class Circle implements Shape { public void draw() { /* ... */ } }
class Rectangle implements Shape { public void draw() { /* ... */ } }
class Triangle implements Shape { public void draw() { /* ... */ } }

// =========== 3. LSP 里氏替换 ===========
// 反例：Square 继承 Rectangle，破坏了宽高可独立设置的契约
class Rectangle {
    protected int width, height;
    public void setWidth(int w)  { this.width = w; }
    public void setHeight(int h) { this.height = h; }
    public int getArea() { return width * height; }
}
class Square extends Rectangle {
    @Override public void setWidth(int w)  { this.width = w; this.height = w; }
    @Override public void setHeight(int h) { this.width = h; this.height = h; }
    // setWidth(5); setHeight(4); 期望面积 20，Square 给出 16
}
// 正例：让两者都实现共同抽象，而不是强行继承
interface Shape2 { int getArea(); }
class Rect2  implements Shape2 { /* 独立宽高 */ public int getArea() { return 0; } }
class Square2 implements Shape2 { /* 单一边长 */ public int getArea() { return 0; } }

// =========== 4. ISP 接口隔离 ===========
// 反例：胖接口逼 Fish 实现 fly()
interface Animal { void eat(); void fly(); void swim(); }
class Fish implements Animal {
    public void eat()  { /* ok */ }
    public void fly()  { throw new UnsupportedOperationException(); }
    public void swim() { /* ok */ }
}
// 正例：拆成能力接口，实现类按需组合
interface Eatable   { void eat(); }
interface Flyable   { void fly(); }
interface Swimmable { void swim(); }
class Fish2 implements Eatable, Swimmable { public void eat() {} public void swim() {} }

// =========== 5. DIP 依赖反转 ===========
// 反例：高层 OrderService 直接 new 出底层 MySQL 实现
class OrderServiceBad {
    private MySQLOrderDao dao = new MySQLOrderDao();
}
// 正例：依赖抽象，由 Spring 容器在运行期注入实现
interface OrderDao { Order findById(long id); }
class MySQLOrderDao implements OrderDao { public Order findById(long id) { return null; } }
@Service
class OrderService {
    private final OrderDao dao;
    public OrderService(OrderDao dao) { this.dao = dao; }
}
